-- 185: Original BrillaPrep WASSCE BrillaPrep transitional Woodwork beta content blueprint questions, part 6.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_185_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_185_guard;
INSERT INTO _migration_185_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_woodwork_b003_026' AND NOT (q.topic_id IS 'topic_was_woodwork_b003_6' AND q.subject_id IS 'subj_wassce_woodwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is a back panel fitted to a cabinet carcass?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Carry every shelf load without the sides","B. Help keep the carcass square and resist racking","C. Replace all corner joints","D. Prevent doors from being fitted"]' AND q.correct_answer IS 'B' AND q.explanation IS 'A securely fixed panel acts as a diaphragm, stabilising the rectangular box against diagonal distortion. Therefore the correct answer is B: Help keep the carcass square and resist racking.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_woodwork_b003_6' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_woodwork_b003_026' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Woodwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_185_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_woodwork_b003_027' AND NOT (q.topic_id IS 'topic_was_woodwork_b003_6' AND q.subject_id IS 'subj_wassce_woodwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the purpose of a kick rail or plinth beneath a floor cabinet?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Suspend the cabinet from the ceiling","B. Replace the cabinet back","C. Support and protect the carcass while providing foot clearance","D. Force doors to open inward"]' AND q.correct_answer IS 'C' AND q.explanation IS 'The base transfers load, raises panels away from floor moisture and can provide a recessed toe space for comfortable use. Therefore the correct answer is C: Support and protect the carcass while providing foot clearance.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_woodwork_b003_6' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_woodwork_b003_027' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Woodwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_185_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_woodwork_b003_028' AND NOT (q.topic_id IS 'topic_was_woodwork_b003_6' AND q.subject_id IS 'subj_wassce_woodwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why are diagonal braces used in a simple timber gate?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Increase hinge friction intentionally","B. Carry only decorative surface finish","C. Make the joints independent of load direction","D. Prevent the rectangular frame from sagging into a parallelogram"]' AND q.correct_answer IS 'D' AND q.explanation IS 'A correctly oriented brace transfers the unsupported corner load toward the lower hinged side and resists racking. Therefore the correct answer is D: Prevent the rectangular frame from sagging into a parallelogram.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_woodwork_b003_6' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_woodwork_b003_028' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Woodwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_185_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_woodwork_b003_029' AND NOT (q.topic_id IS 'topic_was_woodwork_b003_6' AND q.subject_id IS 'subj_wassce_woodwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which construction allows a solid-wood panel to move across the grain within a door frame?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Frame-and-panel construction with the panel free in grooves","B. Glue the panel rigidly across its full width","C. Nail every panel edge without clearance","D. Use only end-grain blocks across the panel"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The surrounding frame provides strength while the floating panel can expand and shrink without splitting or forcing joints apart. Therefore the correct answer is A: Frame-and-panel construction with the panel free in grooves.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_woodwork_b003_6' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_woodwork_b003_029' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Woodwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_185_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_woodwork_b003_030' AND NOT (q.topic_id IS 'topic_was_woodwork_b003_6' AND q.subject_id IS 'subj_wassce_woodwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why are drawer runners installed parallel and level with each other?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Make the drawer progressively narrower in use","B. Allow smooth movement without binding or twisting the drawer","C. Transfer all load to the drawer front","D. Prevent the drawer bottom supporting contents"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Aligned runners maintain consistent clearance and share load, whereas skewed supports rack the drawer and cause friction. Therefore the correct answer is B: Allow smooth movement without binding or twisting the drawer.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_woodwork_b003_6' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_woodwork_b003_030' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Woodwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
